import { Group, Mesh, PlaneGeometry, BufferGeometry, Float32BufferAttribute, DirectionalLight, AmbientLight, Color, OctahedronGeometry, BufferAttribute } from 'three/webgpu';
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, mix, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {any} textContent
 * @property {any[]} cinematicPrimitives
 * @property {any} intent
 * @property {any} visualSpec
 * @property {string} [imageUrl]
 * @property {string} [depthMapUrl]
 * @property {string} [meshUrl]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

export default function createNode(config, ctx) {
	// helpers
	const toRGB = (hex) => {
		const c = new Color(hex);
		return [c.r, c.g, c.b];
	};

	// Root group
	const root = new Group();
	root.name = 'prism-node';

	/*** BACKDROP ***/
	const backdropGeometry = new PlaneGeometry(7, 6);
	const backdropMaterial = new MeshBasicNodeMaterial({
		colorNode: mix(
			vec3(...toRGB('#0b0b10')),
			vec3(...toRGB('#16161d')),
			uv().y
		)
	});
	const backdrop = new Mesh(backdropGeometry, backdropMaterial);
	backdrop.position.set(0, 0, -2.5);
	root.add(backdrop);

	/*** LIGHTING ***/
	// Ambient fill
	const ambient = new AmbientLight(0xffffff, 0.6);
	root.add(ambient);
	// Back rim light (cool directional from behind‑left)
	const rimLight = new DirectionalLight(0x99cfff, 0.9);
	rimLight.position.set(-2, 1, -2); // behind‑left
	root.add(rimLight);
	// Key light (optional subtle front)
	const keyLight = new DirectionalLight(0xffffff, 1.0);
	keyLight.position.set(2, 4, 3);
	root.add(keyLight);

	/*** PRISM GEOMETRY ***/
	// Build an equilateral triangular prism.
	const side = 1.2; // length of each side of the triangular cross‑section
	const length = 1.8; // extrusion length
	const height = Math.sqrt(3) / 2 * side; // height of triangle
	const verts = [
		// Front face (z = +length/2)
		-side / 2, -height / 3, length / 2,
		side / 2, -height / 3, length / 2,
		0, 2 * height / 3, length / 2,
		// Back face (z = -length/2)
		-side / 2, -height / 3, -length / 2,
		side / 2, -height / 3, -length / 2,
		0, 2 * height / 3, -length / 2,
	];
	const indices = [
		// front triangle
		0, 1, 2,
		// back triangle
		5, 4, 3,
		// sides
		0, 2, 5,
		0, 5, 3,
		2, 1, 4,
		2, 4, 5,
		1, 0, 3,
		1, 3, 4,
	];
	const prismGeometry = new BufferGeometry();
	prismGeometry.setAttribute('position', new Float32BufferAttribute(verts, 3));
	prismGeometry.setIndex(indices);
	prismGeometry.computeVertexNormals();

	const prismMaterial = new MeshPhysicalNodeMaterial({
		transmission: 1.0,
		thickness: 0.9,
		ior: 1.55,
		roughness: 0.08,
		clearcoat: 0.25,
		clearcoatRoughness: 0.1,
		attenuationColor: new Color('#e8ecf2'),
		attenuationDistance: 2.5,
		iridescence: 1.0,
		iridescenceIOR: 1.3,
		iridescenceThicknessRange: [120, 480],
		// Approximate dispersion (strength)
		dispersion: 0.18, // node material field (if unsupported will be ignored)
		color: new Color('#ffffff')
	});
	const prismMesh = new Mesh(prismGeometry, prismMaterial);
	// Rotations: 12° on Z, 20° on Y
	prismMesh.rotation.z = THREE.MathUtils.degToRad(12);
	prismMesh.rotation.y = THREE.MathUtils.degToRad(20);
	root.add(prismMesh);

	/*** EMISSIVE CORE ***/
	const coreGeometry = new OctahedronGeometry(0.35);
	const coreMaterial = new MeshPhysicalNodeMaterial({
		color: new Color('#ff2a38'),
		emissive: new Color('#ff2a38'),
		emissiveIntensity: 2.2,
		roughness: 0.5,
		metalness: 0.0
	});
	const coreMesh = new Mesh(coreGeometry, coreMaterial);
	coreMesh.position.set(0, 0, 0);
	root.add(coreMesh);

	/*** CAUSTIC STREAK ***/
	const streakGeometry = new PlaneGeometry(2.4, 0.5);
	const causticMaterial = new MeshBasicNodeMaterial({
		colorNode: mix(
			mix(
				vec3(...toRGB('#ff2a38')),
				vec3(...toRGB('#e8ecf2')),
				smoothstep(0.2, 0.5, uv().x)
			),
			vec3(...toRGB('#9fb0c4')),
			smoothstep(0.5, 0.8, uv().x)
		),
		transparent: true,
		opacity: 0.35
	});
	const streak = new Mesh(streakGeometry, causticMaterial);
	streak.rotation.x = -Math.PI / 2;
	streak.position.set(0, -1.1, 0);
	root.add(streak);

	/*** TEXT ***/
	const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
	for (const item of textItems) {
		const opts = {
			fontSize: item.typography?.fontSize ?? (item.role === 'headline' ? 68 : 18),
			color: '#e8ecf2',
			align: 'center',
			letterSpacingPx: item.typography?.letterSpacing ? item.typography.letterSpacing * item.typography.fontSize : 0
		};
		const textObj = ctx.fontAtlas.createText(item.text, opts);
		const isHeadline = item.role === 'headline' || /headline/i.test(item.text);
		if (isHeadline) {
			textObj.position.set(0, -1.75, 0.1); // slightly in front of prism
		} else {
			textObj.position.set(0, -2.25, 0.1);
		}
		root.add(textObj);
	}

	/*** CINEMATIC PRIMITIVE: depth‑rotate ***/
	const primitiveHandles = [];
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			if (prim.name === 'depth-rotate' && prim.trigger === 'hover') {
				const handle = ctx.primitives['depth-rotate'](root, prim.params ?? { maxDeg: 10 });
				primitiveHandles.push(handle);
			}
		}
	}

	/*** USERDATA & CLEANUP ***/
	const timelines = []; // collect any GSAP timelines if added later

	root.userData.handlers = {}; // no external DOM handlers required

	root.userData.cleanup = () => {
		// dispose geometries & materials
		backdropGeometry.dispose();
		backdropMaterial.dispose();
		prismGeometry.dispose();
		prismMaterial.dispose();
		coreGeometry.dispose();
		coreMaterial.dispose();
		streakGeometry.dispose();
		causticMaterial.dispose();

		// dispose lights (three disposes automatically on removal)
		ambient.dispose();
		rimLight.dispose();
		keyLight.dispose();

		// clean primitives
		for (const h of primitiveHandles) {
			if (h && typeof h.cleanup === 'function') h.cleanup();
		}
		// kill GSAP timelines
		for (const tl of timelines) {
			if (tl && tl.isActive && tl.kill) tl.kill();
		}
	};

	return root;
}
